	array(
		'question_text'  => 'A client offers a therapist a small handmade gift during a culturally significant celebration. What is the most appropriate response?',
		'option_a'       => 'Explore the gift’s meaning, value, cultural context, and possible effect on treatment before deciding',
		'option_b'       => 'Accept the gift automatically because cultural traditions override boundary concerns',
