	array(
		'question_text'  => 'A therapist offers a temporary reduced fee to a client who has recently lost employment. Which approach best protects the therapeutic relationship?',
		'option_a'       => 'Clearly explain and document the arrangement, apply reasonable criteria, establish a review point, and ensure that the decision is not driven by favoritism or personal attachment',
